class Show:
    def __init__(self, title, rating=3):
        self.title = title
        self.rating = rating

    @property
    def rating(self):
        return self._rating

    @rating.setter
    def rating(self, value):
        if not 1 <= value <= 5:
            raise ValueError("rating must be 1-5")
        self._rating = value

    def __str__(self):
        return f"{self.title} ({self.rating}/5)"

print(Show("Dark", 5))
